    [1220368] = { en = "$@spelldesc1213201", description = "$@spelldesc1213201" },
    [1220410] = { en = "Sets an enemy aflame, inflicting $o1 Fire damage over $d. and sending it into a state of panic. While the target is affected, the flames periodically scorch its nearby allies for $1220411s1 damage as well.\r\n", description = "Incendia un nemico, infliggendogli $o1 danni da Fuoco in $d. e gettandolo nel panico. Finché il bersaglio è affetto dall'effetto, le fiamme bruciano periodicamente anche i suoi alleati vicini, infliggendo loro $1220411s1 danni.\r\n" },
    [1220431] = { en = "Applies an aura that will detonate if not reapplied or removed within $d1 seconds. Dissipates after $d2 seconds.\r\n", description = "Applica un'aura che detonerà se non viene riapplicata o rimossa entro $d1 secondi. Si dissipa dopo $d2 secondi.\r\n" },
    [1220521] = { en = "When struck has a $h% chance of reducing the attacker's movement speed by $1220520s1% for 5 secs.", description = "Quando vieni colpito, hai una probabilità del $h% di ridurre la velocità di movimento dell'attaccante del $1220520s1% per 5 secondi." },
    [1220533] = { en = "Call forth the dead to grab hold of nearby enemies, rooting them in place for $d.", description = "Evoca i morti affinché afferrino i nemici vicini, immobilizzandoli per $d." },
    [1220562] = { en = "Transforms you into a Human for $d.", description = "Ti trasformi in un Umano per $d." },
    [1220565] = { en = "Summons and dismisses War.  This is a very fast mount.", description = "Evoca e congeda War. Questa è una cavalcatura molto veloce." },
    [1220566] = { en = "Summons and dismisses Conquest.  This is a very fast mount.", description = "Evoca e congeda Conquest. Questa è una cavalcatura molto veloce." },
    [1220567] = { en = "Summons and dismisses Death.  This is a very fast mount.", description = "Evoca e congeda Death. Questa è una cavalcatura molto veloce." },
    [1220568] = { en = "Summons and dismisses Famine.  This is a very fast mount.", description = "Evoca e congeda Famine. Questa è una cavalcatura molto veloce." },
    [1220596] = { en = "Improves your chance to get a critical strike by $s1%.", description = "Aumenta la probabilità di mettere a segno un colpo critico del $s1%." },
    [1220623] = { en = "Permanently enchant a Shield to add $1220596M1% critical strike chance.", description = "Incanta permanentemente uno scudo per aumentare la probabilità di colpo critico del $1220596M1%." },
    [1220624] = { en = "Permanently enchant Bracers to add $M1 to spell power.", description = "Incanta permanentemente dei bracciali per aumentare la potenza magica di $M1." },
    [1220642] = { en = "Increases the amount healed by your Chain Heal, Riptide, and Earth Shield spells by $s1%.", description = "Aumenta le cure generate dagli incantesimi Catena di Guarigione, Marea Benefica e Scudo di Terra del $s1%." },
    [1220645] = { en = "Increases the amount healed by your Holy Light, and Holy Shock shock spells by $s1%, and the amount absorbed by your Sacred Shield spell by $s1%.", description = "Aumenta le cure generate dagli incantesimi Luce Sacra e Folgore Sacra del $s1% e l'assorbimento dello scudo generato dall'incantesimo Scudo Sacro del $s1%." },
    [1220702] = { en = "Increases the amount healed by your Nourish, Wild Growth, and Efflorescence spells by $s1%.", description = "Aumenta le cure generate dagli incantesimi Nutrizione, Crescita Selvaggia ed Efflorescenza del $s1%." },
    [1220830] = { en = "Boom.", description = "Boom." },
    [1220925] = { en = "\r\n\r\n", description = "\r\n\r\n" },
    [1220980] = { en = "Equipped with state of the art Creepy Censor Sensors, allowing you to see anything! \r\n\r\nDisclaimer: Goggles may not allow you to see much at all.", description = "Dotato di sensori censori inquietanti all'avanguardia, ti permette di vedere qualsiasi cosa! \r\n\r\nAvvertenza: gli occhiali potrebbero non permetterti di vedere granché." },
    [1221309] = { en = "Don the insignia of the Scarlet Crusade.  While wearing $M1 pieces of the crafted Scarlet Military set or the Tabard of the Scarlet Enclave, your disguise will fool many crusaders in New Avalon.", description = "Indossa le insegne della Crociata Scarlatta. Se indossi $M1 pezzi del set militare scarlatto artigianale o il Tabardo dell'Enclave Scarlatta, il tuo travestimento ingannerà molti crociati a Nuova Avalon." },
    [1221341] = { en = "$@spelldesc1221337", description = "$@spelldesc1221337" },
    [1222771] = { en = "Launches fire infused orbs towards a random player that travels out. Players hit are inflicted with $s1 Fire damage", description = "Lancia sfere infuse di fuoco verso un giocatore casuale, che si allontanano. I giocatori colpiti subiscono $s1 danni da Fuoco" },
    [1222988] = { en = "Your Earthbind Totem Immobilizes nearby targets for $1238289d when cast.", description = "Quando viene lanciato, il tuo Totem Vincolaterra immobilizza i bersagli vicini per $1238289d." },
    [1223030] = { en = "Reduces the mana cost of your Shock and Lightning Shield spells by $s1%.", description = "Riduce il costo in mana degli incantesimi Folgore e Scudo di Fulmini del $s1%." },
    [1223031] = { en = "When you Stormstrike, you have a $m1% chance to gain $1238931s1% mana regeneration while casting spells for $1238931d, and Stormstrike's cooldown has a $m2% chance to reset each time you Dodge or Parry.", description = "Quando usi Assalto della Tempesta, hai una probabilità del $m1% di ottenere una rigenerazione del mana pari al $1238931s1% mentre lanci incantesimi per $1238931d; inoltre, il tempo di recupero di Assalto della Tempesta ha una probabilità del $m2% di azzerarsi ogni volta che schivi o pari." },
    [1223033] = { en = "Allows $m1% of your Mana regeneration to continue while casting.", description = "Consente al $m1% della tua rigenerazione del Mana di proseguire durante il lancio degli incantesimi." },
    [1223081] = { en = "Increases the periodic damage and healing done by your spells and abilities by $s1%.", description = "Aumenta del $s1% i danni periodici e le cure inflitti dai tuoi incantesimi e dalle tue abilità." },
}
for id, record in pairs(records) do
    local current = ns.data.spellDescriptionOverrides[id]
    if current == nil then
        ns.data.spellDescriptionOverrides[id] = record
    end
end
